/**
 * dsh-decision-gateway — 客户端契约消费层（api/ 域内模块，经 interface.ts 门面引用）。
 *
 * 类型直接复用共享 ConfigV1/HistoryEntry/DecisionLang/DecisionTier/AutomationCap/AutomationLevel；
 * 解析/归一/校验为纯函数（可单测直连）。主代理裁决：automationCap 三档 0|1|2；
 * GET /config 裸 v1 掩码体并兼容 {config}/{data} 包装；失败体含 errorCode + category。
 * 零 bare import。
 */
import type {
  AutomationCap,
  AutomationLevel,
  ConfigV1 as SharedConfigV1,
  HistoryEntry as SharedHistoryEntry,
  DecisionLang,
  DecisionTier,
} from "../../shared/interface.ts";
import { t } from "../locale.ts";

/** 共享类型复出（子模块经 api/interface.ts 消费）。 */
export type { AutomationCap, AutomationLevel, DecisionLang, DecisionTier };
export type DecisionConfigV1 = SharedConfigV1;
export type DecisionHistoryEntry = SharedHistoryEntry;

/** 预设开关项（配置 v1.presets 元素形态）。 */
export type DecisionPresetConfigEntry = SharedConfigV1["presets"][number];

/** 模板库目录项（GET /presets 元素形态；服务端字段缺失时容错）。 */
export interface DecisionPresetInfo {
  readonly id: string;
  readonly templateVersion?: number;
  readonly label?: string;
  readonly description?: string;
  readonly custom?: boolean;
}

function pickCategory(body: unknown): string | null {
  if (body === null || typeof body !== "object" || Array.isArray(body)) return null;
  const rec = body as Record<string, unknown>;
  const nested = rec["error"];
  if (nested !== null && typeof nested === "object" && !Array.isArray(nested)) {
    const nrec = nested as Record<string, unknown>;
    for (const key of ["category", "errorCode", "code"]) {
      const v = nrec[key];
      if (typeof v === "string" && v.length > 0) return v;
    }
  }
  for (const key of ["category", "errorCode", "error", "code"]) {
    const v = rec[key];
    if (typeof v === "string" && v.length > 0) return v;
  }
  const msg = rec["message"];
  if (typeof msg === "string" && msg.length > 0) return msg;
  return null;
}

export function failureCategory(status: number, body: unknown): string {
  const hit = pickCategory(body);
  if (hit !== null) return hit;
  if (status === 403) return "forbidden-non-loopback";
  if (status === 405) return "method-not-allowed";
  if (status === 400) return "bad-request";
  return "http-" + status;
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

function asNumber(v: unknown, fallback: number): number {
  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
}

/** automationCap 归一到 0|1|2（非法回 0=none）。 */
export function normalizeCap(v: unknown): AutomationCap {
  if (v === 1 || v === 2) return v;
  if (v === 0) return 0;
  if (typeof v === "string") {
    if (v === "high" || v === "2") return 2;
    if (v === "low" || v === "1") return 1;
  }
  if (typeof v === "number" && Number.isFinite(v)) {
    if (v >= 2) return 2;
    if (v >= 1) return 1;
  }
  return 0;
}

export function capLabel(cap: AutomationCap): string {
  if (cap === 2) return "high";
  if (cap === 1) return "low";
  return t("capNone");
}

/** 防御式解析 GET /config（裸 v1 或 {config}/{data} 包装均接受）。 */
export function parseConfigPayload(payload: unknown): DecisionConfigV1 | null {
  const raw: unknown =
    isRecord(payload) && "config" in payload
      ? (payload as Record<string, unknown>)["config"]
      : isRecord(payload) &&
          "data" in payload &&
          isRecord((payload as Record<string, unknown>)["data"])
        ? (payload as Record<string, unknown>)["data"]
        : payload;
  if (!isRecord(raw)) return null;
  if (raw["version"] !== 1) return null;
  const conn = isRecord(raw["connection"]) ? (raw["connection"] as Record<string, unknown>) : null;
  const hist = isRecord(raw["history"]) ? (raw["history"] as Record<string, unknown>) : null;
  const presetsRaw = Array.isArray(raw["presets"]) ? (raw["presets"] as unknown[]) : null;
  if (conn === null || hist === null || presetsRaw === null) return null;
  const presets: Array<{
    readonly id: string;
    readonly enabled: boolean;
    readonly automationCap: AutomationCap;
  }> = [];
  for (const item of presetsRaw) {
    if (!isRecord(item) || typeof item["id"] !== "string") continue;
    presets.push({
      id: item["id"] as string,
      enabled: item["enabled"] === true,
      automationCap: normalizeCap(item["automationCap"]),
    });
  }
  const apiKeyRef = conn["apiKeyRef"];
  return {
    version: 1,
    connection: {
      apiKeyRef: typeof apiKeyRef === "string" ? apiKeyRef : undefined,
      hasPlaintextKey: conn["hasPlaintextKey"] === true,
      timeoutMs: asNumber(conn["timeoutMs"], 8000),
      maxConcurrency: asNumber(conn["maxConcurrency"], 4),
      truncBudget: asNumber(conn["truncBudget"], 32000),
    },
    presets,
    history: {
      perSession: asNumber(hist["perSession"], 200),
      totalSessions: asNumber(hist["totalSessions"], 50),
    },
  };
}

/** 防御式解析 GET /presets（裸数组或 {presets} 包装均接受）。 */
export function parsePresetsPayload(payload: unknown): DecisionPresetInfo[] {
  const list: unknown =
    isRecord(payload) && Array.isArray(payload["presets"])
      ? payload["presets"]
      : Array.isArray(payload)
        ? payload
        : isRecord(payload) && Array.isArray(payload["data"])
          ? payload["data"]
          : [];
  const out: DecisionPresetInfo[] = [];
  for (const item of list as unknown[]) {
    if (!isRecord(item) || typeof item["id"] !== "string") continue;
    const tv = item["templateVersion"];
    const label = item["label"];
    const desc = item["description"];
    const custom = item["custom"];
    out.push({
      id: item["id"] as string,
      templateVersion: typeof tv === "number" && Number.isFinite(tv) ? tv : undefined,
      label: typeof label === "string" ? label : undefined,
      description: typeof desc === "string" ? desc : undefined,
      custom: custom === true ? true : undefined,
    });
  }
  return out;
}

function normalizeAutomation(v: unknown): AutomationLevel {
  if (v === "assisted" || v === "auto" || v === "manual") return v;
  return "manual";
}

/** 防御式解析题目快照（形状不对即丢整列，不阻断条目）。 */
function parseQuestions(raw: unknown): DecisionHistoryEntry["questions"] {
  if (!Array.isArray(raw)) return undefined;
  const out: {
    readonly id: string;
    readonly text: string;
    readonly kind: "choice" | "score";
    readonly options?: readonly string[];
    readonly levels?: readonly string[];
  }[] = [];
  for (const item of raw as unknown[]) {
    if (item === null || typeof item !== "object" || Array.isArray(item)) return undefined;
    const rec = item as Record<string, unknown>;
    if (typeof rec["id"] !== "string" || typeof rec["text"] !== "string") return undefined;
    const kind = rec["kind"];
    if (kind !== "choice" && kind !== "score") return undefined;
    const options = rec["options"];
    const levels = rec["levels"];
    out.push({
      id: rec["id"] as string,
      text: rec["text"] as string,
      kind,
      ...(Array.isArray(options) && options.every((o) => typeof o === "string")
        ? { options: (options as string[]).slice() }
        : {}),
      ...(Array.isArray(levels) && levels.every((o) => typeof o === "string")
        ? { levels: (levels as string[]).slice() }
        : {}),
    });
  }
  return out;
}

/** 防御式解析 GET /history（裸数组或 {entries}/{items}/{history}/{data} 包装均接受）。 */
const str = (v: unknown, fb = ""): string => (typeof v === "string" ? v : fb);
const optStr = (v: unknown): string | undefined => (typeof v === "string" ? v : undefined);
const num = (v: unknown, fb: number): number => asNumber(v, fb);
const enumOf = <T extends string>(v: unknown, xs: readonly T[], fb: T): T =>
  (xs as readonly unknown[]).includes(v) ? (v as T) : fb;
const optScore = (v: unknown): number | undefined =>
  typeof v === "number" && Number.isFinite(v) ? v : undefined;
const F: Array<[string, (v: unknown) => unknown]> = [
  ["rootHash", str],
  ["rootDisplay", str],
  ["presetId", str],
  ["templateVersion", (v) => num(v, 1)],
  ["stateHash", str],
  ["snippetRedacted", str],
  ["resultKind", str],
  ["tier", (v) => enumOf(v, ["high", "low"] as const, "none")],
  ["lang", (v) => enumOf(v, ["en", "zh"] as const, "unknown")],
  ["automation", (v) => normalizeAutomation(v)],
  ["truncated", (v) => v === true],
  ["originalLength", (v) => num(v, 0)],
  ["confidence", (v) => num(v, 0)],
  ["latencyMs", (v) => num(v, 0)],
  ["choice", optStr],
  ["score", optScore],
  ["errorCode", optStr],
];
export function toHistoryEntry(it: unknown): DecisionHistoryEntry | null {
  if (!isRecord(it)) return null;
  if (typeof it.ts !== "number" || typeof it.sessionId !== "string") return null;
  const o: Record<string, unknown> = { ts: it.ts, sessionId: it.sessionId, provider: "official" };
  for (const [k, f] of F) o[k] = f(it[k]);
  o.presetTitle = optStr(it.presetTitle);
  if (typeof it.sessionTitle === "string" && it.sessionTitle.length > 0)
    o.sessionTitle = it.sessionTitle;
  const q = parseQuestions(it.questions);
  if (q !== undefined) o.questions = q;
  return o as unknown as DecisionHistoryEntry;
}
export function parseHistoryPayload(payload: unknown): DecisionHistoryEntry[] {
  let list: unknown = [];
  if (Array.isArray(payload)) list = payload;
  else if (isRecord(payload)) {
    for (const key of ["entries", "items", "history", "data"]) {
      const v = payload[key];
      if (Array.isArray(v)) {
        list = v;
        break;
      }
    }
  }
  const out: DecisionHistoryEntry[] = [];
  for (const item of list as unknown[]) {
    const entry = toHistoryEntry(item);
    if (entry !== null) out.push(entry);
  }
  return out;
}

/** ENV 名本地校验（与共享 API_KEY_REF_RE 同正则）。 */
export function validApiKeyRef(name: string): boolean {
  return /^[A-Z][A-Z0-9_]{1,63}$/.test(name);
}

/** 0..1 概率钳制（概率条宽度与文案同源；与 automationCap 三档无关）。 */
export function clamp01(v: unknown): number {
  if (typeof v !== "number" || !Number.isFinite(v)) return 0;
  if (v < 0) return 0;
  if (v > 1) return 1;
  return v;
}

/**
 * dsh-decision-gateway — 客户端传输层（api/ 域内模块，经 interface.ts 门面引用）。
 *
 * 路由回退取共享 ROUTES（宿主单一事实源经构建期 __DSH_ROUTES__ 注入时优先注入值）。
 * 零 bare import。
 */
import { ROUTES } from "../../shared/interface.ts";

/** 构建期注入的宿主路由表（bundle-host extraDefine；缺席即 undefined）。 */
declare const __DSH_ROUTES__: Record<string, string> | undefined;

/** 取注入值（非字符串/缺席即回落共享 ROUTES）。 */
function injected(key: string, fallback: string): string {
  if (typeof __DSH_ROUTES__ !== "undefined") {
    const value: unknown = (__DSH_ROUTES__ as Record<string, unknown>)[key];
    if (typeof value === "string" && value.length > 0) return value;
  }
  return fallback;
}

/** 卡片实际使用的路由表（注入优先，共享兜底）。 */
export const APP_ROUTES: {
  readonly health: string;
  readonly config: string;
  readonly presets: string;
  readonly history: string;
  readonly testConnection: string;
} = {
  health: injected("health", ROUTES.health),
  config: injected("config", ROUTES.config),
  presets: injected("presets", ROUTES.presets),
  history: injected("history", ROUTES.history),
  testConnection: injected("testConnection", ROUTES.testConnection),
};

/** 客户端 fetch 默认超时（浏览器→dsh web 一跳；与 provider-usage 10s 先例对齐）。 */
export const CLIENT_FETCH_TIMEOUT_MS = 10_000;

export function fetchTimeout(
  url: string,
  init?: RequestInit,
  timeoutMs: number = CLIENT_FETCH_TIMEOUT_MS,
): Promise<Response> {
  if (init?.signal !== undefined) return fetch(url, init);
  return fetch(url, { ...init, signal: AbortSignal.timeout(timeoutMs) });
}

/**
 * dsh-decision-gateway — 浏览器端（自包含干净模块，React externals）。
 *
 * 在「设置」面板注册独立 tab「JEV 决策」（settings.section 插槽，order 80；
 * 缺插槽即 tab 不挂载）。React 由构建期 external 注入（经 factory 注入的
 * require("react") 解析，dsh web 不暴露全局 React）。契约外壳由
 * scripts/build/build-client.ts 统一生成——源码不写任何 loader 痕迹。
 * 样式独立 style.css，经 .css text-loader 构建期内联。卸载清理进 ctx.effect。
 */
import STYLE from "./style.css";
import { ensureStyle } from "../../../../shared/client/ensure-style.js";
import * as React from "react";
import { bindTranslate, t, unbindTranslate, type HostTranslate } from "./locale.ts";
import { en, zh } from "./locales.ts";
import { DecisionCard } from "./settings/card.tsx";

const STYLE_ID = "dsh-decision-gateway-style";
const CSS_VERSION = "1";
/** 宿主 locale 字典命名空间（register/bind/subscribe 同名；notifier 同款）。 */
const NS = "decision-gateway";

/** 宿主插槽读形态（本包只用 settings.section 的 inject/register；缺失即 tab 不挂载）。 */
interface SlotsView {
  inject: (name: string, setup: () => unknown) => unknown;
  register: (item: Record<string, unknown>, render: () => unknown) => unknown;
}

/** 宿主 locale 服务读形态（本包只用 register/bind/subscribe/getSnapshot；缺失即回落本地字典）。 */
interface LocaleServiceView {
  register: (ns: string, dict: { zh: unknown; en: unknown }) => void;
  bind: (ns: string) => unknown;
  // subscribe 可返回 undefined（provider-usage/mcp-manager 同款形态）：调用方一律按
  // undefined 守卫登记卸载，不预设返回非空——类型与守卫、测试三方对齐，防名实不符。
  subscribe?: (listener: () => void) => (() => void) | undefined;
  getSnapshot?: () => unknown;
}

/** 浏览器端上下文窄面（实际使用的面：get + effect；与 inject 对齐）。 */
interface ClientContext {
  get: (name: string) => unknown;
  effect: (execute: () => () => void, label?: string) => unknown;
}

export function apply(ctx: ClientContext): void {
  try {
    const disposeStyle = ensureStyle({ id: STYLE_ID, cssText: STYLE, version: CSS_VERSION });
    let styleDisposed = false;
    const slots = ctx.get("slots") as SlotsView | null | undefined;
    if (slots === null || slots === undefined || typeof slots.inject !== "function") {
      console.warn("[dsh-decision-gateway] 缺少 slots 服务，设置 tab 未挂载");
      return;
    }
    // i18n：注册本插件字典；t 绑定宿主 locale 服务（notifier 同款），订阅回调重绑，
    // 切语言免刷新跟随；未装配（旧运行时）回落本地字典，界面照常渲染。
    // 订阅取消函数供 disposer 卸载调用（守卫对齐 notifier 的 undefined 形态——不预设
    // subscribe 返回 null，防其返回 null 时 null 初始化遮蔽导致守卫失效）。
    let unsubLocale: (() => void) | undefined;
    const locale = ctx.get("locale") as LocaleServiceView | null | undefined;
    if (locale !== null && locale !== undefined && typeof locale.register === "function") {
      // 收窄后的别名：嵌套回调内 narrowing 会重置，别名本身即非空类型，回调内照常可用。
      const localeService = locale;
      // bind/subscribe 必须带接收者调用：宿主实现依赖 this，detached 摘出即抛，失败被
      // catch 兜住后回落本地字典（notifier 同款注释，防后人“简化”成 detached 调用）。
      // 重绑单点：初装与订阅回调共用——bind 抛错/返回非函数同样回落本地字典
      // （bindTranslate 内二次守住）；初绑失败不订阅（与重构前语义一致）。
      const rebind = (): boolean => {
        let next: unknown;
        try {
          next = localeService.bind(NS);
        } catch (e) {
          console.warn("[dsh-decision-gateway] locale 重绑失败：", e);
          return false;
        }
        if (typeof next !== "function") {
          console.warn("[dsh-decision-gateway] locale bind 返回非函数，已回落本地字典");
          return false;
        }
        bindTranslate(next as HostTranslate);
        return true;
      };
      try {
        localeService.register(NS, { zh: zh, en: en });
        const boundOk = rebind();
        if (
          boundOk &&
          typeof localeService.subscribe === "function" &&
          typeof localeService.getSnapshot === "function"
        ) {
          unsubLocale = localeService.subscribe(function () {
            rebind();
          });
        }
      } catch (e) {
        console.warn("[dsh-decision-gateway] locale 注册失败：", e);
      }
    }
    // 设置面板独立 tab（settings.section）：旧运行时无此插槽即回调不执行，
    // tab 不挂载——不做 plugin.item 双插槽重复展示。
    // label 传 thunk：宿主 nav 每次读取经 thunk 求值 + shell 订阅 locale 重渲染，
    // 切语言即跟随（注册期求值字符串快照是旧行为）；thunk 内只调 t(key)，不包抛错逻辑。
    try {
      slots.inject("settings.section", function () {
        return slots.register(
          {
            name: "settings.section",
            id: "dsh-decision-gateway",
            order: 80,
            label: () => t("tabLabel"),
          },
          function () {
            return <DecisionCard />;
          },
        );
      });
    } catch (e) {
      console.warn("[dsh-decision-gateway] 设置 tab 注册失败：", e);
    }
    if (unsubLocale !== undefined) {
      const unsubscribe = unsubLocale;
      ctx.effect(function () {
        return function () {
          try {
            unsubscribe();
          } catch {
            /* 卸载期静默 */
          }
          // 摘除模块级宿主绑定：否则 bound 残留 stale 宿主实现，卸载后 t() 不再回落。
          unbindTranslate();
        };
      }, "dsh-decision-gateway-locale");
    }
    ctx.effect(function () {
      return function () {
        if (styleDisposed) return;
        styleDisposed = true;
        try {
          disposeStyle();
        } catch {
          /* 卸载期静默 */
        }
      };
    }, "dsh-decision-gateway");
  } catch (e) {
    console.warn("[dsh-decision-gateway] 挂载失败：", e);
  }
}

// ---- 客户端契约：apply/inject 由 build-client 经 factory 装配（干净模块，React externals） ----
export const inject: string[] = ["slots", "locale"];

/**
 * dsh-decision-gateway — 客户端文案绑定（零依赖纯函数，可被 node 单测直测）。
 *
 * 语言判定：浏览器 locale 以 zh 开头即中文，其余英文（含缺 navigator 的 node 环境
 * 回落英文——与 JEV 英文问答更擅长一致）。单测经 setLang 锁定语言。
 *
 * 宿主 locale 服务（notifier 同款）：apply 期 register 字典 + bind 装配，订阅回调重绑，
 * 切语言免刷新跟随；未装配（旧运行时 / 单测直调）回落本地字典——界面照常渲染中文案。
 */
import { en, zh } from "./locales.ts";

export type DecisionLocale = "zh" | "en";
export type DecisionTextKey = keyof typeof zh;

/** 宿主装配的翻译函数（官方 ctx.locale.bind(ns) 产物；key 即本包字典键）。 */
export type HostTranslate = (key: string, params?: Record<string, unknown>) => string;

let current: DecisionLocale = resolveLang();
let bound: HostTranslate | null = null;

/** 装配 / 重绑宿主翻译函数（apply 期与 locale 订阅回调调用）。
 * 守住 bound 恒可调用：宿主异常实现可能返回非函数（命名空间未命中等），
 * 此时忽略装配、t() 回落本地字典（此前本地路径永不抛错，回归面见评审）。 */
export function bindTranslate(next: HostTranslate): void {
  if (typeof next !== "function") return;
  bound = next;
}

/** 摘除宿主绑定、回落本地字典（卸载 / 单测隔离用）。 */
export function unbindTranslate(): void {
  bound = null;
}

/** 解析当前语言（浏览器 zh 开头即 zh，否则 en）。 */
export function resolveLang(): DecisionLocale {
  try {
    const nav = (globalThis as unknown as { navigator?: { language?: unknown } }).navigator;
    const lang = nav?.language;
    if (typeof lang === "string" && lang.toLowerCase().startsWith("zh")) return "zh";
  } catch {
    /* 忽略 */
  }
  return "en";
}

/** 锁定语言（单测用；正常渲染走模块加载期解析）。 */
export function setLang(next: DecisionLocale): void {
  current = next;
}

/** 当前语言。 */
export function lang(): DecisionLocale {
  return current;
}

/** 取文案（key 即 zh 源；缺 key 永不发生——en 由 Record<keyof typeof zh> 锁死）。
 * 支持 {n} 数字插值（中英语序不同，禁止空串 key 占位）。 */
export function t(key: DecisionTextKey, params?: { readonly n?: number }): string {
  if (bound !== null) return bound(key, params === undefined ? undefined : { n: params.n });
  const raw = current === "zh" ? zh[key] : en[key];
  if (params?.n === undefined) return raw;
  return raw.replaceAll("{n}", String(params.n));
}

/**
 * dsh-decision-gateway — 设置独立页卡片（React，宿主 settings.section 插槽渲染）。
 *
 * 三 tab（连接/模板库/历史，一 tab 一主焦点）+ 健康徽标。样式独立 style.css。
 */
import * as React from "react";
import { APP_ROUTES, fetchTimeout } from "../api/interface.ts";
import { t } from "../locale.ts";
import { ConnectionPane } from "./connection.tsx";
import { HistoryPane } from "./history.tsx";
import { PresetsPane } from "./presets.tsx";

type TabKey = "connection" | "presets" | "history";

const TABS: ReadonlyArray<{
  readonly key: TabKey;
  readonly textKey: "tabConnection" | "tabPresets" | "tabHistory";
}> = [
  { key: "connection", textKey: "tabConnection" },
  { key: "presets", textKey: "tabPresets" },
  { key: "history", textKey: "tabHistory" },
];

export function DecisionCard(): React.ReactElement {
  const [active, setActive] = React.useState<TabKey>("connection");
  const [healthText, setHealthText] = React.useState(t("healthChecking"));
  const [healthCls, setHealthCls] = React.useState("dj-badge");
  const alive = React.useRef(true);
  React.useEffect(() => {
    alive.current = true;
    void fetchTimeout(APP_ROUTES.health, { headers: { accept: "application/json" } })
      .then((res) => {
        if (!alive.current) return;
        setHealthText(res.ok ? t("healthOk") : t("healthBad") + res.status);
        setHealthCls(res.ok ? "dj-badge dj-statusOk" : "dj-badge dj-statusErr");
      })
      .catch(() => {
        if (!alive.current) return;
        setHealthText(t("healthUnreachable"));
        setHealthCls("dj-badge dj-statusErr");
      });
    return () => {
      alive.current = false;
    };
  }, []);

  return (
    <section className="dj-card" data-plugin="dsh-decision-gateway">
      <div className="dj-head">
        <span className={healthCls}>{healthText}</span>
      </div>
      <div className="dj-tabs" role="group" aria-label={t("tabsAria")}>
        {TABS.map((tab) => (
          <button
            key={tab.key}
            type="button"
            className={tab.key === active ? "dj-tab dj-tabActive" : "dj-tab"}
            aria-selected={tab.key === active ? "true" : "false"}
            onClick={() => setActive(tab.key)}
          >
            {t(tab.textKey)}
          </button>
        ))}
      </div>
      <div className="dj-body">
        {active === "connection" && <ConnectionPane />}
        {active === "presets" && <PresetsPane />}
        {active === "history" && <HistoryPane />}
      </div>
    </section>
  );
}

/**
 * dsh-decision-gateway — 连接 tab（React，settings.section 独立页）。
 *
 * 要素：密钥二选一卡（radio 互斥，未选中轨整体隐藏；切轨保存自动清对方）/
 * 离线自检 / 高级折叠 / 保存。Key 永不回显原文；placeholder 禁真密钥示例。
 * 保存语义与 vanilla 一致：互斥阻断、ENV 形状校验、明文免二次确认、
 * 未知键永不发送、保存后清空明文框并重载掩码态。
 */
import * as React from "react";
import {
  APP_ROUTES,
  failureCategory,
  fetchTimeout,
  parseConfigPayload,
  validApiKeyRef,
} from "../api/interface.ts";
import type { DecisionConfigV1 } from "../api/interface.ts";
import { t } from "../locale.ts";

type Msg = { readonly kind: "info" | "error" | "ok"; readonly text: string };

export function ConnectionPane(): React.ReactElement {
  const [snapshot, setSnapshot] = React.useState<DecisionConfigV1 | null>(null);
  const [keyMode, setKeyMode] = React.useState<"env" | "plain">("env");
  const [env, setEnv] = React.useState("");
  const [plain, setPlain] = React.useState("");
  const [timeoutMs, setTimeoutMs] = React.useState("8000");
  const [maxConcurrency, setMaxConcurrency] = React.useState("4");
  const [truncBudget, setTruncBudget] = React.useState("32000");
  const [perSession, setPerSession] = React.useState("200");
  const [totalSessions, setTotalSessions] = React.useState("50");
  const [msg, setMsg] = React.useState<Msg | null>(null);
  const [testOut, setTestOut] = React.useState("");
  const [testing, setTesting] = React.useState(false);
  const [saving, setSaving] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const [plainOpen, setPlainOpen] = React.useState(false);
  const [advOpen, setAdvOpen] = React.useState(false);
  const alive = React.useRef(true);
  React.useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);

  const load = React.useCallback(() => {
    setFailed(false);
    setMsg({ kind: "info", text: t("loading") });
    void fetchTimeout(APP_ROUTES.config, { headers: { accept: "application/json" } })
      .then(async (res) => {
        if (!alive.current) return;
        if (!res.ok) {
          let cat = "http-" + res.status;
          try {
            cat = failureCategory(res.status, await res.json());
          } catch {
            /* 非 JSON 即保持状态码类别 */
          }
          throw new Error(cat);
        }
        const cfg = parseConfigPayload(await res.json());
        if (cfg === null) throw new Error("config-shape-unknown");
        setSnapshot(cfg);
        setEnv(cfg.connection.apiKeyRef ?? "");
        setPlain("");
        // 按存量同步轨道（ENV 优先，无绑定回落 ENV）：首屏不再永远停在 ENV。
        setKeyMode(
          cfg.connection.apiKeyRef ? "env" : cfg.connection.hasPlaintextKey ? "plain" : "env",
        );
        setTimeoutMs(String(cfg.connection.timeoutMs));
        setMaxConcurrency(String(cfg.connection.maxConcurrency));
        setTruncBudget(String(cfg.connection.truncBudget));
        setPerSession(String(cfg.history.perSession));
        setTotalSessions(String(cfg.history.totalSessions));
        setMsg({ kind: "info", text: t("loadedNote") });
      })
      .catch((e: unknown) => {
        if (!alive.current) return;
        setSnapshot(null);
        setFailed(true);
        setMsg({
          kind: "error",
          text: t("loadFail") + (e instanceof Error ? e.message : String(e)),
        });
      });
  }, []);
  React.useEffect(load, [load]);

  const useEnv = keyMode === "env";
  const conn = snapshot?.connection;
  const mask =
    conn === undefined ? t("notLoaded") : conn.hasPlaintextKey ? t("maskOn") : t("maskOff");

  const save = (): void => {
    if (snapshot === null || saving) return;
    const envName = useEnv ? env.trim() : "";
    const plainValue = !useEnv ? plain : "";
    if (plainValue !== "" && envName !== "") {
      setMsg({ kind: "error", text: t("mutualError") });
      return;
    }
    if (envName !== "" && !validApiKeyRef(envName)) {
      setMsg({ kind: "error", text: t("envBad") });
      return;
    }
    const nums = [timeoutMs, maxConcurrency, truncBudget, perSession, totalSessions].map(Number);
    if (!nums.every((n) => Number.isFinite(n))) {
      setMsg({ kind: "error", text: t("nanError") });
      return;
    }
    const body: Record<string, unknown> = {
      version: 1,
      connection: {
        timeoutMs: nums[0],
        maxConcurrency: nums[1],
        truncBudget: nums[2],
        ...(plainValue !== "" ? {} : envName !== "" ? { apiKeyRef: envName } : {}),
      },
      presets: snapshot.presets.map((p) => ({
        id: p.id,
        enabled: p.enabled,
        automationCap: p.automationCap,
      })),
      history: { perSession: nums[3], totalSessions: nums[4] },
      ...(plainValue !== "" ? { apiKeyPlaintext: plainValue } : {}),
      // 切 ENV→明文：附 apiKeyRef:null 清掉已存引用，否则服务端互斥 400。
      ...(plainValue !== "" && snapshot.connection.apiKeyRef ? { apiKeyRef: null } : {}),
    };
    setSaving(true);
    setMsg({ kind: "info", text: t("saving") });
    void fetchTimeout(APP_ROUTES.config, {
      method: "PUT",
      headers: { "content-type": "application/json", accept: "application/json" },
      body: JSON.stringify(body),
    })
      .then(async (res) => {
        if (!alive.current) return;
        if (!res.ok) {
          let cat = "http-" + res.status;
          try {
            const b: unknown = await res.json();
            if (b !== null && typeof b === "object") {
              const rec = b as Record<string, unknown>;
              const nested = rec["error"];
              if (nested !== null && typeof nested === "object" && !Array.isArray(nested)) {
                const v =
                  (nested as Record<string, unknown>)["category"] ??
                  (nested as Record<string, unknown>)["errorCode"];
                if (typeof v === "string" && v.length > 0) cat = v;
              } else {
                const v = rec["category"] ?? rec["errorCode"] ?? rec["error"] ?? rec["code"];
                if (typeof v === "string" && v.length > 0) cat = v;
              }
            }
          } catch {
            /* 忽略 */
          }
          throw new Error(cat);
        }
        setPlain("");
        setMsg({ kind: "ok", text: t("savedReload") });
        load();
      })
      .catch((e: unknown) => {
        if (!alive.current) return;
        setMsg({
          kind: "error",
          text: t("saveFail") + (e instanceof Error ? e.message : String(e)),
        });
      })
      .finally(() => {
        if (alive.current) setSaving(false);
      });
  };

  const selfCheck = (): void => {
    if (testing) return;
    setTesting(true);
    setTestOut(t("testing"));
    void fetchTimeout(APP_ROUTES.testConnection, {
      method: "POST",
      headers: { "content-type": "application/json", accept: "application/json" },
      body: "{}",
    })
      .then(async (res) => {
        if (!alive.current) return;
        let category = "";
        try {
          const body: unknown = await res.json();
          const hit = failureCategory(res.status, body);
          if (hit !== "http-" + res.status) category = hit;
        } catch {
          /* 非 JSON 即按状态码 */
        }
        setTestOut(
          res.ok
            ? category !== ""
              ? t("testOk") + "（" + category + "）"
              : t("testOk")
            : t("testFail") + (category !== "" ? category : "http-" + res.status),
        );
      })
      .catch((e: unknown) => {
        if (!alive.current) return;
        setTestOut(t("testFail") + (e instanceof Error ? e.message : String(e)));
      })
      .finally(() => {
        if (alive.current) setTesting(false);
      });
  };

  return (
    <div className="dj-pane" data-tab="connection">
      <div className="dj-tools">
        <span className={conn?.hasPlaintextKey ? "dj-badge dj-badgeOn" : "dj-badge"}>{mask}</span>
        {conn?.hasPlaintextKey === true && (
          <span className="dj-note" aria-label={t("maskDotsAria")}>
            {"••••••••"}
          </span>
        )}
        {conn?.apiKeyRef !== undefined && conn.apiKeyRef !== "" && (
          <span className="dj-badge">
            {t("maskEnv")}
            {conn.apiKeyRef}
          </span>
        )}
      </div>
      {msg !== null && (
        <div className="dj-field">
          <span className={msg.kind === "error" ? "dj-errLine" : "dj-note"}>{msg.text}</span>
        </div>
      )}
      <div className="dj-field" role="radiogroup" aria-label={t("keyMode")}>
        <label>{t("keyMode")}</label>
        <div className="dj-tools">
          <label>
            <input
              type="radio"
              name="dj-keymode"
              value="env"
              checked={useEnv}
              onChange={() => setKeyMode("env")}
            />
            {t("keyEnv")}
          </label>
          <label>
            <input
              type="radio"
              name="dj-keymode"
              value="plain"
              checked={!useEnv}
              onChange={() => setKeyMode("plain")}
            />
            {t("keyPlain")}
          </label>
        </div>
        <span className="dj-note">{useEnv ? t("modeEnvNote") : t("modePlainNote")}</span>
      </div>
      {useEnv ? (
        <div className="dj-field">
          <label>{t("envLabel")}</label>
          <input
            className="dj-input"
            aria-label={t("envAria")}
            inputMode="text"
            autoComplete="off"
            value={env}
            placeholder={t("envPlaceholder")}
            onChange={(e) => setEnv(e.target.value)}
          />
          <span className="dj-note">{t("envRule")}</span>
        </div>
      ) : (
        <div className="dj-fold">
          <button type="button" className="dj-foldHead" onClick={() => setPlainOpen((v) => !v)}>
            <span>{t("plainFoldTitle")}</span>
            <span>{plainOpen ? "▾" : "▸"}</span>
          </button>
          <div className="dj-foldBody" hidden={!plainOpen}>
            <div className="dj-field">
              <input
                className="dj-input"
                type="password"
                aria-label={t("plainAria")}
                autoComplete="off"
                value={plain}
                placeholder={t("plainPlaceholder")}
                onChange={(e) => setPlain(e.target.value)}
              />
              <span className="dj-note">{t("plainNote")}</span>
            </div>
          </div>
        </div>
      )}
      <div className="dj-tools">
        <button type="button" className="dj-btn dj-btnSmall" disabled={testing} onClick={selfCheck}>
          {t("testOffline")}
        </button>
        <span className="dj-note">{testOut}</span>
      </div>
      <div className="dj-fold">
        <button type="button" className="dj-foldHead" onClick={() => setAdvOpen((v) => !v)}>
          <span>{t("advTitle")}</span>
          <span>{advOpen ? "▾" : "▸"}</span>
        </button>
        <div className="dj-foldBody" hidden={!advOpen}>
          {(
            [
              [t("advTimeout"), timeoutMs, setTimeoutMs, t("advTimeoutHint")],
              [t("advConcurrency"), maxConcurrency, setMaxConcurrency, t("advConcurrencyHint")],
              [t("advTrunc"), truncBudget, setTruncBudget, t("advTruncHint")],
              [t("advPerSession"), perSession, setPerSession, t("advPerSessionHint")],
              [t("advTotalSessions"), totalSessions, setTotalSessions, t("advTotalSessionsHint")],
            ] as Array<[string, string, (v: string) => void, string]>
          ).map(([label, value, set, hint]) => (
            <div className="dj-field" key={label}>
              <label>{label}</label>
              <input
                className="dj-input"
                inputMode="numeric"
                autoComplete="off"
                value={value}
                onChange={(e) => set(e.target.value)}
              />
              <span className="dj-note">{hint}</span>
            </div>
          ))}
        </div>
      </div>
      <div className="dj-foot">
        {failed && (
          <button type="button" className="dj-btn dj-btnSmall" onClick={load}>
            {t("retry")}
          </button>
        )}
        <button
          type="button"
          className="dj-btn dj-btnPrimary"
          disabled={saving || snapshot === null}
          onClick={save}
        >
          {t("save")}
        </button>
      </div>
    </div>
  );
}

/** dsh-decision-gateway — 纯显示格式函数（零依赖，可单测直连）。 */
export function fmtTime(ts: number): string {
  if (typeof ts !== "number" || !Number.isFinite(ts)) return "";
  try {
    const d = new Date(ts);
    const pad = (n: number): string => (n < 10 ? "0" + n : String(n));
    return (
      d.getFullYear() +
      "-" +
      pad(d.getMonth() + 1) +
      "-" +
      pad(d.getDate()) +
      " " +
      pad(d.getHours()) +
      ":" +
      pad(d.getMinutes()) +
      ":" +
      pad(d.getSeconds())
    );
  } catch {
    return "";
  }
}

/** 短 id（超长截断；完整值放 title）。 */
export function shortId(id: string, len = 8): string {
  if (id.length <= len) return id;
  return id.slice(0, len);
}

